solutionCodeJson.code:
// 3 tests: line 11 is evaluated once per call, so True and False need two non-empty calls.
const DC_TESTS = [
  { id: 'UTCID01', input: { orders: [], isMember: false }, expected: 0, status: 'P' },
  { id: 'UTCID02', input: { orders: [-5000, 600000, 20000], isMember: true }, expected: 122, status: 'P' },  // skip, double, normal; no cap
  { id: 'UTCID03', input: { orders: [20000000], isMember: false }, expected: 1000, status: 'P' },            // cap
];

// MC/DC line 2: null (A alone) and [] (B alone). Line 8: (T,T) + (T,F) in one member call, (F,·) in a non-member call.
const MCDC_TESTS = [
  { id: 'UTCID01', input: { orders: null, isMember: false }, expected: 0 },
  { id: 'UTCID02', input: { orders: [], isMember: false }, expected: 0 },
  { id: 'UTCID03', input: { orders: [-5000, 600000, 20000], isMember: true }, expected: 122 },
  { id: 'UTCID04', input: { orders: [20000000], isMember: false }, expected: 1000 },
];

// Tests derived from the specification — they pass on the correct code and kill every mutant.
describe('calcLoyaltyPoints', () => {
  test('null and empty lists give 0', () => {
    expect(calcLoyaltyPoints(null, true)).toBe(0);
    expect(calcLoyaltyPoints([], true)).toBe(0);
  });
  test('1 point per FULL 10,000 VND (25,000 → 2)', () => {
    expect(calcLoyaltyPoints([25000], false)).toBe(2);
  });
  test('non-positive amounts are ignored', () => {
    expect(calcLoyaltyPoints([-50000, 0, 30000], false)).toBe(3);
  });
  test.each([
    [499999, 49],    // below the threshold: not doubled
    [500000, 100],   // exactly 500,000: doubled
  ])('member order of %i earns %i', (amount, points) => {
    expect(calcLoyaltyPoints([amount], true)).toBe(points);
  });
  test('non-members are never doubled', () => {
    expect(calcLoyaltyPoints([600000], false)).toBe(60);
  });
  test('the total is capped at 1,000', () => {
    expect(calcLoyaltyPoints([20000000], false)).toBe(1000);
  });
});

